<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$doc=(int)($_GET['id']??0);$s=$db->prepare('SELECT * FROM project_documents WHERE id=?');$s->execute([$doc]);$d=$s->fetch();if(!$d){http_response_code(404);exit('Document not found.');}if($d['visibility']!=='admin'){$path=__DIR__.'/../'.ltrim($d['file_path'],'/');}else{$path=__DIR__.'/../'.ltrim($d['file_path'],'/');}if(!is_file($path)){http_response_code(404);exit('File not found.');}$mime=(string)($d['mime_type']?:'application/octet-stream');header('Content-Type: '.$mime);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace(['"',"\r","\n"],'_',basename($d['file_name'])).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;